from pathlib import Path
import ast
import base64
import re

ROOT = Path.cwd()
DRIVER = ROOT / "wa_backend" / "api" / "driver.py"
MODELS = ROOT / "wa_backend" / "models.py"
SCHEMAS = ROOT / "wa_backend" / "schemas.py"
SERVICES = ROOT / "wa_backend" / "services.py"

BLOCK_MAIN = base64.b64decode("").decode("utf-8")
BLOCK_VISITS = base64.b64decode("").decode("utf-8")


def abort(message: str):
    print(f"PATCH_ABORT: {message}")
    raise SystemExit(1)


def read(path: Path) -> str:
    if not path.exists():
        abort(f"الملف غير موجود: {path}")
    return path.read_text(encoding="utf-8")


def replace_section(text: str, start_marker: str, end_marker: str, replacement: str, label: str) -> str:
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        abort(f"تعذر تحديد مقطع {label} بشكل آمن.")
    start = text.index(start_marker)
    end = text.index(end_marker, start)
    return text[:start] + replacement + text[end:]


def replace_inside_section(text: str, start_marker: str, end_marker: str, old: str, new: str, label: str) -> str:
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        abort(f"تعذر تحديد قسم {label}.")
    start = text.index(start_marker)
    end = text.index(end_marker, start)
    section = text[start:end]
    if old in section:
        if section.count(old) != 1:
            abort(f"مرساة {label} تكررت داخل القسم.")
        section = section.replace(old, new, 1)
    elif new not in section:
        abort(f"تعذر إثبات أو تطبيق {label}.")
    return text[:start] + section + text[end:]


driver = read(DRIVER)
models = read(MODELS)
schemas = read(SCHEMAS)
services = read(SERVICES)

# Support files are validation-only; this patch never writes them.
if "class VisitReturn(Base):" not in models or "batch_id           = Column(Integer, nullable=False" not in models:
    abort("models.py لا يحتوي VisitReturn.batch_id الإجباري.")
if "fk_visit_return_tenant_batch" not in models or "class InventoryTransferHeader(Base):" not in models:
    abort("models.py لا يحتوي بنية Batch/HANDSHAKE الموحدة المطلوبة.")
if "class VisitUpdateRequest(RequestModel):" not in schemas or "request_id: UUID" not in schemas:
    abort("schemas.py لا يحتوي request_id المطلوب للزيارة.")
if "class VisitReturnInput(RequestModel):" not in schemas or "batch_id: PositiveDbInt" not in schemas:
    abort("schemas.py لا يحتوي batch_id الإجباري للمرتجع.")
if "async def apply_inventory_movements_batch(" not in services:
    abort("services.py لا يحتوي محرك الحركات الموحد.")
if "# PATCH: DRIVER_UNIFIED_VISIT_INVENTORY" not in driver:
    abort("driver.py لا يحتوي استعادة update_visit الموحدة؛ نفّذ باتش الاستعادة أولاً.")

LEGACY = (
    "InventoryTransfer",
    "SessionInventory",
    "VehicleLoad",
    "MainWarehouse",
    "InventoryLedger",
    "WarehouseLedger",
)


def legacy_counts(text: str):
    return {
        name: len(re.findall(r"\b" + re.escape(name) + r"\b", text))
        for name in LEGACY
    }


counts_before = legacy_counts(driver)
if all(value == 0 for value in counts_before.values()) and "async def _load_vehicle_inventory_projection(" in driver:
    try:
        ast.parse(driver)
    except SyntaxError as exc:
        abort(f"driver.py الحالي مكسور نحوياً رغم أنه يبدو مهاجراً: {exc}")
    print("DRIVER_REMAINING_UNIFIED_OK_ALREADY")
    print("LEGACY_SYMBOLS_OK: 0")
    raise SystemExit(0)

# Migrate dashboard + handshake + pending polling in one bounded section.
driver = replace_section(
    driver,
    "# =========================================\n# 5. جلب بيانات الداشبورد للمندوب",
    "# =========================================\n# 9. إضافة محل جديد",
    BLOCK_MAIN,
    "Dashboard/HANDSHAKE",
)

# Migrate Flutter/offline inventory and pending transfer projection.
driver = replace_section(
    driver,
    "# =========================================\n# 11. استعراض زيارات اليوم والجرد",
    "# =========================================\n# 12. جلب تفاصيل الزيارة المكتملة",
    BLOCK_VISITS,
    "/driver/visits",
)

# Tenant hardening for the remaining simple endpoints.
driver = replace_inside_section(
    driver,
    "# =========================================\n# 9. إضافة محل جديد",
    "# =========================================\n# 10. قائمة المنتجات والأسعار",
    "stmt_session = select(WorkSession).filter_by(driver_id=driver_id, end_time=None).order_by(WorkSession.id.desc()).limit(1)",
    "stmt_session = select(WorkSession).filter_by(company_id=current_driver.company_id, driver_id=driver_id, end_time=None).order_by(WorkSession.id.desc()).limit(1)",
    "add_new_shop active session tenant scope",
)
driver = replace_inside_section(
    driver,
    "# =========================================\n# 9. إضافة محل جديد",
    "# =========================================\n# 10. قائمة المنتجات والأسعار",
    "stmt_route = select(DispatchRoute).filter_by(work_session_id=active_session.id, status='active')",
    "stmt_route = select(DispatchRoute).filter_by(company_id=current_driver.company_id, work_session_id=active_session.id, driver_id=driver_id, status='active')",
    "add_new_shop route tenant scope",
)
driver = replace_inside_section(
    driver,
    "# =========================================\n# 10. قائمة المنتجات والأسعار",
    "# =========================================\n# 11. استعراض زيارات اليوم والجرد",
    "stmt = select(ProductVariant).filter_by(is_active=True).order_by(ProductVariant.id.asc())",
    "stmt = select(ProductVariant).filter_by(company_id=current_driver.company_id, is_active=True).order_by(ProductVariant.id.asc())",
    "product catalog tenant scope",
)
driver = replace_inside_section(
    driver,
    "# =========================================\n# 12. جلب تفاصيل الزيارة المكتملة",
    "# =========================================\n# 13. التحقق من وجود جلسة نشطة للمندوب",
    ").filter_by(id=visit_id)",
    ").filter_by(company_id=current_driver.company_id, id=visit_id)",
    "visit details tenant scope",
)
# Last section runs to EOF.
active_marker = "# =========================================\n# 13. التحقق من وجود جلسة نشطة للمندوب"
if driver.count(active_marker) != 1:
    abort("تعذر تحديد قسم active session.")
active_start = driver.index(active_marker)
active_section = driver[active_start:]
old_active = "stmt_session = select(WorkSession).filter_by(driver_id=driver_id, end_time=None).order_by(WorkSession.id.desc()).limit(1)"
new_active = "stmt_session = select(WorkSession).filter_by(company_id=current_driver.company_id, driver_id=driver_id, end_time=None).order_by(WorkSession.id.desc()).limit(1)"
if old_active in active_section:
    if active_section.count(old_active) != 1:
        abort("مرساة active session tenant scope تكررت.")
    active_section = active_section.replace(old_active, new_active, 1)
elif new_active not in active_section:
    abort("تعذر إثبات أو تطبيق active session tenant scope.")
driver = driver[:active_start] + active_section

try:
    ast.parse(driver)
except SyntaxError as exc:
    abort(f"الناتج غير صالح نحوياً: {exc}")

remaining = {name: count for name, count in legacy_counts(driver).items() if count}
if remaining:
    abort(f"بقيت مراجع Legacy في driver.py: {remaining}")

required_tokens = (
    "async def _load_vehicle_inventory_projection(",
    '"movement_kind": "RESERVATION"',
    '"reservation_action": "RELEASE"',
    '"reference_type": "HANDSHAKE_POST"',
    'workflow_type="HANDSHAKE"',
    'status="PENDING"',
    'InventoryBalance.stock_status == "AVAILABLE"',
    'company_id=current_driver.company_id, is_active=True',
)
for token in required_tokens:
    if token not in driver:
        abort(f"Post-condition مفقود: {token}")

DRIVER.write_text(driver, encoding="utf-8")

print("DRIVER_REMAINING_UNIFIED_OK")
print("DASHBOARD_OK: InventoryBalance + InventoryMovement only; API shape preserved")
print("HANDSHAKE_OK: PENDING reservation -> accept RELEASE+PHYSICAL / reject RELEASE")
print("OFFLINE_OK: /driver/visits uses unified vehicle inventory and new pending headers")
print("TENANT_SCOPE_OK: remaining driver read endpoints hardened with company_id")
print("LEGACY_SYMBOLS_OK: InventoryTransfer/SessionInventory/VehicleLoad/MainWarehouse/InventoryLedger/WarehouseLedger = 0")
print("NEXT_STAGE: run py_compile + git diff --check, then final driver audit")
